package com.bank.flink.ckpt;

import java.math.BigDecimal;

// A stream record: either a normal transaction OR a checkpoint barrier.
class Record {
    private final boolean barrier;
    private final long checkpointId;      // valid when barrier == true
    private final String accountId;       // valid when barrier == false
    private final BigDecimal amount;

    private Record(boolean barrier, long checkpointId, String accountId, BigDecimal amount) {
        this.barrier = barrier;
        this.checkpointId = checkpointId;
        this.accountId = accountId;
        this.amount = amount;
    }

    static Record txn(String accountId, BigDecimal amount) {
        return new Record(false, -1, accountId, amount);
    }

    static Record barrier(long checkpointId) {
        return new Record(true, checkpointId, null, null);
    }

    boolean isBarrier() { return barrier; }
    long getCheckpointId() { return checkpointId; }
    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
}
