package com.bank.flink.ckpt;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Single-input operator: updates balances, snapshots when a barrier arrives.
class BalanceOperator {
    private static final Logger log = Logger.getLogger(BalanceOperator.class.getName());

    private final Map<String, BigDecimal> balances = new HashMap<>();
    private Map<String, BigDecimal> lastSnapshot = new HashMap<>();

    void process(Record r, CheckpointCoordinator coordinator) {
        if (r.isBarrier()) {
            // snapshot asynchronously then forward the barrier (single input: no alignment)
            lastSnapshot = new HashMap<>(balances);
            log.info(() -> "BalanceOperator snapshot ckpt=" + r.getCheckpointId()
                    + " state=" + lastSnapshot);
            coordinator.acknowledge("BalanceOperator", r.getCheckpointId());
            return;
        }
        balances.merge(r.getAccountId(), r.getAmount(), BigDecimal::add);
    }

    void restore() {
        balances.clear();
        balances.putAll(lastSnapshot);
        log.info(() -> "BalanceOperator restored state=" + balances);
    }

    Map<String, BigDecimal> getBalances() { return balances; }
}
