package com.bank.flink.ckpt;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.logging.Logger;

// Two-input operator: performs BARRIER ALIGNMENT. It buffers records from an
// input that has already barriered, and only snapshots once BOTH inputs barrier.
class MergeOperator {
    private static final Logger log = Logger.getLogger(MergeOperator.class.getName());

    private final Set<String> barrieredInputs = new HashSet<>();
    private final List<Record> buffered = new ArrayList<>();
    private int mergedCount = 0;

    // inputName is "retail" or "corporate".
    void process(String inputName, Record r, CheckpointCoordinator coordinator) {
        if (r.isBarrier()) {
            barrieredInputs.add(inputName);
            log.info(() -> "MergeOperator received barrier on " + inputName
                    + " (" + barrieredInputs.size() + "/2 aligned)");
            if (barrieredInputs.size() == 2) {
                // ALIGNED: snapshot now, then drain buffered records.
                log.info(() -> "MergeOperator ALIGNED ckpt=" + r.getCheckpointId()
                        + " snapshot mergedCount=" + mergedCount);
                coordinator.acknowledge("MergeOperator", r.getCheckpointId());
                for (Record b : buffered) mergedCount++;
                buffered.clear();
                barrieredInputs.clear();
            }
            return;
        }
        // If this input already barriered, buffer its post-barrier records.
        if (barrieredInputs.contains(inputName)) {
            buffered.add(r);
            log.fine(() -> "MergeOperator buffering post-barrier record from " + inputName);
        } else {
            mergedCount++;
        }
    }

    int getMergedCount() { return mergedCount; }
}
