package com.bank.flink.ckpt;

import java.util.HashSet;
import java.util.Set;
import java.util.logging.Logger;

// The JobManager coordinator: triggers barriers, collects acks, declares complete.
class CheckpointCoordinator {
    private static final Logger log = Logger.getLogger(CheckpointCoordinator.class.getName());

    private final int expectedOperators;
    private final Set<String> acked = new HashSet<>();
    private long currentCheckpointId = 0;
    private boolean complete = false;

    CheckpointCoordinator(int expectedOperators) {
        this.expectedOperators = expectedOperators;
    }

    long triggerCheckpoint() {
        currentCheckpointId++;
        acked.clear();
        complete = false;
        log.info(() -> "Coordinator TRIGGER checkpoint " + currentCheckpointId);
        return currentCheckpointId;
    }

    void acknowledge(String operator, long checkpointId) {
        if (checkpointId == currentCheckpointId) {
            acked.add(operator);
            if (acked.size() == expectedOperators) {
                complete = true;
                log.info(() -> "Coordinator checkpoint " + checkpointId + " COMPLETE (all acked)");
            }
        }
    }

    boolean isComplete() { return complete; }
    long getCurrentCheckpointId() { return currentCheckpointId; }
}
