package com.bank.flink.ckpt;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: barriers flow, merge aligns, snapshots ack, crash+restore.
public class BarrierCheckpointDemo {
    private static final Logger log = Logger.getLogger(BarrierCheckpointDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new CkptLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CheckpointCoordinator coordinator = new CheckpointCoordinator(2); // Balance + Merge
        BalanceOperator balanceOp = new BalanceOperator();
        MergeOperator mergeOp = new MergeOperator();

        // Normal processing before the checkpoint.
        balanceOp.process(Record.txn("SAV2001", new BigDecimal("1000")), coordinator);
        balanceOp.process(Record.txn("CUR3001", new BigDecimal("500")), coordinator);
        mergeOp.process("retail", Record.txn("SAV2001", new BigDecimal("1000")), coordinator);

        // Coordinator triggers a checkpoint: inject barriers at the source.
        long ckptId = coordinator.triggerCheckpoint();
        Record barrier = Record.barrier(ckptId);

        // Barrier reaches the single-input balance operator.
        balanceOp.process(barrier, coordinator);

        // Barrier alignment at the merge operator: retail barriers first,
        // a post-barrier record arrives and is buffered, then corporate barriers.
        mergeOp.process("retail", barrier, coordinator);
        mergeOp.process("retail", Record.txn("SAV2001", new BigDecimal("50")), coordinator); // buffered
        mergeOp.process("corporate", Record.txn("CUR3001", new BigDecimal("700")), coordinator); // pre-barrier
        mergeOp.process("corporate", barrier, coordinator); // now ALIGNED -> snapshot

        log.info(() -> "Checkpoint complete? " + coordinator.isComplete());

        // CRASH + RESTORE.
        log.info(() -> "--- simulating crash + restore ---");
        balanceOp.getBalances().clear();
        balanceOp.restore();
        log.info(() -> "Recovered SAV2001 = " + balanceOp.getBalances().get("SAV2001"));
    }
}

